#!/usr/bin/env python3
"""Results summary for the revised analysis (amendment 2). Every number is read from a saved file; nothing is typed by hand."""
import json, glob, os, csv
P = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..")); T = os.path.join(P, "results/tables/")
J = lambda f: json.load(open(os.path.join(P, f))); f = lambda x: f"{x:,}"
L = []; A = L.append
flow = J("data/derived/faers_q/report_flow.json"); cc = J("data/derived/faers_q/case_characteristics.json"); sb = J("data/derived/faers_q/b/summary.json")
man = list(csv.DictReader(open(os.path.join(P, "data/raw/faers_quarterly/MANIFEST.tsv")), delimiter="\t"))
A("# Results summary, revised analysis (amendment 2) — generated from saved result files\n")
A("Generated by `code/python/make_results_summary_r2.py`. Round-1 results (before the internal review) are in `results/round1/`.")
A("Primary extraction (b): primary + secondary suspect drugs; fixed-dose-combination-only mentions excluded. Targets: human protein targets (single protein, family, complex). Two profile variants are reported side by side: **PRR / standard cleaning** (the ranking fixed in SAP v1) and **IC025 / extended cleaning** (added after internal review).\n")
A("## 1. Data flow [`data/raw/faers_quarterly/MANIFEST.tsv`, `MANIFEST_demoext.tsv`, `data/derived/faers_q/report_flow.json`]")
A(f"- {len(man)} quarterly files, 2004Q1–2026Q3, {sum(int(r['zip_bytes']) for r in man)/1e9:.2f} GB zipped. DEMO rows {f(flow['demo_rows_all_versions'])} → {f(flow['cases_after_dedup'])} cases after case-level deduplication → **{f(flow['cases_after_field_duplicate_removal'])}** after field-based duplicate removal ({f(flow['field_duplicates_removed'])} removed; the rule could be applied to {f(flow['cases_with_fields_for_duplicate_check'])} cases that had event date, age and sex).")
tot = flow['drug_rows_in_dedup_cases']; m = flow['drug_rows_by_mapping_source']
A(f"- Drug rows {f(tot)}: " + ", ".join(f"{k} {f(v)} ({100*v/tot:.1f}%)" for k, v in m.items()) + f". Ingredients seen {f(flow['ingredients_seen'])}; distinct preferred terms {f(flow['distinct_pt'])}.")
A("\n## 2. Case characteristics [`data/derived/faers_q/case_characteristics.json`]")
n = sum(cc['sex'].values()); A("- Sex: " + ", ".join(f"{k} {f(v)} ({100*v/n:.1f}%)" for k, v in sorted(cc['sex'].items())) + ".")
q = cc['age_years_quartiles']; A(f"- Age in years available for {f(cc['age_in_years_available'])} cases: median {q[1]:.0f} (IQR {q[0]:.0f}–{q[2]:.0f}).")
A("- Country (ten most frequent): " + ", ".join(f"{k} {f(v)}" for k, v in cc['top_countries']) + ".")
A("- Reporter type: " + ", ".join(f"{k} {f(v)}" for k, v in cc['reporter_type']) + ".")
A("\n## 3. Cohort [`data/derived/faers_q/b/summary.json`]")
A(f"- Background cases {f(sb['reports_in_background'])}; molecules with ≥100 suspect reports {f(sb['eligible_molecules'])}; cohort {f(sb['cohort_molecules'])} molecules at {sb['cohort_targets']} human protein targets. Signals in cohort {f(sb['signals_cohort'])}; after standard cleaning {f(sb['clean_signals_cohort'])}; after extended cleaning {f(sb['clean2_signals_cohort'])}.")
A("\n## 4. Shared profile signals, same-target versus different-target molecules [`results/tables/primary_R2_*.json`]")
A("Δ = molecule-averaged difference in shared top-20 signals; node-permutation p; molecule-bootstrap 95% CI. Rows marked * use 9,999 permutations and 10,000 bootstrap resamples, the others 999 and 1,000.\n")
A("| extraction | targets | ranking | cleaning | molecules | same-target pairs | mean same | mean different | Δ | 95% CI | p |"); A("|---|---|---|---|---|---|---|---|---|---|---|")
ext = {"b": "b suspect", "c": "c primary suspect only", "d": "d suspect, health-professional", "e": "e sole suspect", "balltargets": "b suspect"}
for fn in sorted(glob.glob(T + "primary_R2_*.json")):
    lab = os.path.basename(fn)[11:-5]
    if lab.startswith("ctgov"): continue
    r = json.load(open(fn)); x = r["shared_signals"]; e, meas, cl = lab.split("_")
    A(f"| {ext[e]} | {'all ChEMBL' if e == 'balltargets' else 'human protein'} | {meas.upper()} | {'extended' if cl == 'clean2' else 'standard'} | {f(r['n_molecules'])} | {f(r['same_target_pairs'])} | {x['pair_mean_same']} | {x['pair_mean_different']} | {x['delta']}{'*' if r['B_perm'] == 9999 else ''} | {x['ci95'][0]}–{x['ci95'][1]} | {x['p_perm_one_sided']} |")
for lab, nm in (("R2_prr_clean", "PRR / standard cleaning"), ("R2_ic025_clean2", "IC025 / extended cleaning")):
    t = J(f"results/tables/target_vs_class_{lab}.json"); c = J(f"results/tables/comention_summary_{lab[3:]}.json"); a = J(f"results/tables/asof_summary_{lab[3:]}.json"); pc = J(f"results/tables/positive_control_{lab}.json")
    A(f"\n## 5–8 for profile variant: {nm}")
    pe = t["profile_entry_reports"]
    A(f"### Profile description [`target_vs_class_{lab}.json`]\n- {f(pe['entries'])} profile entries; reports behind an entry: median {pe['median']:.0f}; ≤3 reports {pe['pct_le3']}%; ≤10 reports {pe['pct_le10']}%.\n- Pairs sharing no signal: {t['pct_same_target_pairs_sharing_none']}% of same-target and {t['pct_different_target_pairs_sharing_none']}% of different-target pairs.\n- Most frequent shared terms among same-target pairs (term, pairs): " + "; ".join(f"{x[0]} {x[1]}" for x in t["top_shared_terms_same_target"][:15]) + ".")
    A(f"### Target versus class, all {f(t['pairs'])} pairs ({f(t['same_target_pairs'])} same-target) [`target_vs_class_{lab}.json`, `pairs_all_{lab}.csv.gz`]\nMolecules with ATC codes {t['molecules_with_atc']}, with FDA EPC class {t['molecules_with_epc']}.\n")
    A("| stratum | same-target pairs | different-target pairs | mean same target | mean different target | difference | 95% CI |"); A("|---|---|---|---|---|---|---|")
    nmap = {"atc4": "ATC level 4", "atc3": "ATC level 3", "epc": "FDA EPC class", "indication": "indication (top ten)"}
    for k, v in t["within_class_contrasts"].items():
        for c_, d in v.items(): A(f"| {'same' if c_ == 'same_class' else 'different'} {nmap[k]} | {f(d['same_target_pairs'])} | {f(d['different_target_pairs'])} | {d['mean_same_target']} | {d['mean_different_target']} | {d['difference']} | {d['ci95'][0]}–{d['ci95'][1]} |")
    A("\nSame-target coefficient (least squares on all pairs; molecule bootstrap, 500 resamples):")
    for mk, mn in (("model_unadjusted", "unadjusted"), ("model_class_only", "class only (ATC 4, 3, 1; EPC with missing level)"), ("model_full", "full (class + shared indication + report volumes + approval-year gap + co-mention share)"), ("model_full_with_interaction", "full + target × ATC-4 interaction")):
        d = t[mk]["same_target"]; s_ = f"- {mn}: {d['beta']} (95% CI {d['ci95'][0]}–{d['ci95'][1]}; bootstrap share ≤ 0: {d['share_bootstrap_le0']})"
        if "target_x_atc4" in t[mk]: i_ = t[mk]["target_x_atc4"]; s_ += f"; interaction {i_['beta']} ({i_['ci95'][0]}–{i_['ci95'][1]})"
        A(s_ + ".")
    A("- Other coefficients, full model: " + "; ".join(f"{k} {v['beta']} ({v['ci95'][0]}–{v['ci95'][1]})" for k, v in t["model_full"].items() if k not in ("intercept", "same_target")) + ".")
    tl = t["target_level"]; A(f"- Target-level analysis: {tl['targets']} targets; mean contrast {tl['mean_contrast']} (95% CI {tl['ci95'][0]}–{tl['ci95'][1]}); {100*tl['share_targets_positive']:.1f}% of targets positive; median {tl['median']}.")
    A(f"### Co-mention [`comention_summary_{lab[3:]}.json`]")
    for g in ("same", "different"):
        d = c[g]; A(f"- {g} target ({f(d['pairs'])} pairs): median co-mention share {100*d['median_share_max']:.3f}%; ≥5% in {d['pct_share_ge_5pct']}%; none in {d['pct_no_comention']}%; mean overlap {d['mean_overlap_before']} → {d['mean_overlap_after']} after removing reports naming both molecules.")
    A(f"- Difference same − different: {c['difference_before']['estimate']} ({c['difference_before']['ci95'][0]}–{c['difference_before']['ci95'][1]}) before; {c['difference_after']['estimate']} ({c['difference_after']['ci95'][0]}–{c['difference_after']['ci95'][1]}) after. Ratio same/different: {c['ratio_before']} before, {c['ratio_after']} after.")
    o = a["clean"]
    A(f"### As-of-date analysis [`asof_summary_{lab[3:]}.json`, `asof_sets_{lab[3:]}.csv`]")
    A(f"- {a['matched_sets']} matched sets (of {a['candidate_sets']} candidates; dropped {a['dropped']}), {a['clusters']} clusters, {a['distinct_F']} first molecules, {a['distinct_S']} successors; largest cluster {a['largest_cluster_sets']} sets; {a['clusters_with_1_set']} clusters of one set.")
    A(f"- First molecule's as-of profile vs successor: {o['mean_O_F']} shared signals; control A (volume-matched other first molecules) {o['mean_control_A']}; control B (other successors) {o['mean_control_B']}. Sets with ≥1 shared signal: {100*o['share_sets_F_ge1']:.1f}% vs {100*o['share_control_A_ge1']:.1f}% of control-A comparisons.")
    for k_, nm_ in (("eA", "e_A"), ("eB", "e_B"), ("eC", "e_C (controls in the same ATC level-1 group as the first molecule)")):
        A(f"- {nm_} = {o[k_]['estimate']} (95% CI {o[k_]['ci95'][0]}–{o[k_]['ci95'][1]}; cluster sign-flip p {o[k_]['p_signflip_one_sided']}).")
    A(f"- e_A without the largest cluster {a['eA_clean_without_largest_cluster']}; unweighted mean of cluster means {a['eA_clean_unweighted_cluster_mean']}; sets with a class-matched control {a['sets_with_control_C']}.")
    A(f"### Positive control for the trial analysis [`positive_control_{lab}.json`]\n- {pc['molecules_in_both']} molecules in both cohorts: a molecule's FAERS profile shares {pc['mean_own_overlap']} signals with its own trial profile and {pc['mean_other_overlap']} with other molecules' trial profiles (difference {pc['difference']}, 95% CI {pc['ci95'][0]}–{pc['ci95'][1]}); own > other for {pc['pct_molecules_own_gt_other']}% of molecules.")
ct = J("data/derived/ctgov/profile/summary.json"); at = J("data/derived/ctgov/attribution_summary.json"); wt = J("data/derived/ctgov/profile_within_trial/summary.json")
A("\n## 9. Parallel analysis in ClinicalTrials.gov trial-reported adverse events [`data/derived/ctgov/`, `primary_R2_ctgov_*.json`]")
A(f"- {f(at['labels']['exposed'])} monotherapy arms of {f(at['arms'])} result arms (rule v2; audit 93/100 correct by LLM agents, exact 95% interval 86.1–97.1% as computed by the PV reviewer; rule v1 failed: 73/100 and 24/98).")
A(f"- Term matching kept {ct['pct_rows_kept']}% of event rows and {ct['pct_affected_subjects_kept']}% of affected subjects. Molecules meeting minimum data {ct['molecules_meeting_minimum_data']}; cohort {ct['cohort_molecules']} molecules, {ct['cohort_targets']} human protein targets, {f(ct['same_target_pairs_within_cohort_targets'])} same-target pairs; profile entries resting on a term with no background count (background set to 0.5; RR ≥ 2 and chi-square ≥ 4 still required) {ct['profile_entries_with_zero_background']} of {f(ct['profile_entries'])}; of these, entries whose term appears in another molecule's profile {ct['zero_background_entries_whose_term_is_in_another_profile']}.")
for lab, nm in (("R2_ctgov_all", "All pairs"), ("R2_ctgov_no_shared_trial", "Pairs sharing a trial excluded"), ("R2_ctgov_no_shared_condition", "Pairs sharing a top-ten trial condition excluded")):
    r = J(f"results/tables/primary_{lab}.json"); x = r["shared_signals"]
    A(f"- {nm}: {f(r['same_target_pairs'])} same-target, {f(r['different_target_pairs'])} different-target pairs; means {x['pair_mean_same']} vs {x['pair_mean_different']}; Δ = {x['delta']} (95% CI {x['ci95'][0]}–{x['ci95'][1]}; p {x['p_perm_one_sided']}; molecules used {x['molecules_used']}).")
A(f"- Within-trial reference-arm-adjusted version: {wt['molecules_meeting_minimum_data']} molecules meet minimum data; cohort {wt['cohort_molecules']} molecules, {wt['cohort_targets']} targets, {wt['same_target_pairs_within_cohort_targets']} same-target pairs — not assessable against the size thresholds.")
open(os.path.join(P, "results/RESULTS_SUMMARY.md"), "w").write("\n".join(L) + "\n"); print(len(L), "lines written")
